-- Tierwyn baseline schema — the single migration a fresh install needs.
-- Consolidates every migration up to and including 156 (squashed at release; see git history).
-- Generated by replaying the full chain against an in-memory DB and serialising
-- sqlite_master. Do not hand-edit to add objects: add a new numbered migration (next: 2).
--
-- schema_migrations is intentionally absent: apps/server/src/db/migrate.ts owns it.
-- Every statement is idempotent so this file is a safe no-op on a pre-existing DB.

CREATE TABLE IF NOT EXISTS agent_commands (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL REFERENCES agents(id),
  name TEXT NOT NULL,
  label TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  source TEXT NOT NULL DEFAULT 'discovered',
  source_detail TEXT,
  enabled_flag INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS agent_models (
  id           TEXT PRIMARY KEY,
  agent_id     TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  model_name   TEXT NOT NULL,
  label        TEXT NOT NULL,
  provider     TEXT,
  vision_flag  INTEGER NOT NULL DEFAULT 0,
  steer_flag   INTEGER NOT NULL DEFAULT 0,
  enabled_flag INTEGER NOT NULL DEFAULT 1,
  description  TEXT NOT NULL DEFAULT '',
  created_at   INTEGER NOT NULL
, source TEXT NOT NULL DEFAULT 'discovered', max_concurrent_spawns INTEGER, max_grandchild_spawns INTEGER, context_window INTEGER);

CREATE TABLE IF NOT EXISTS agents (
  id              TEXT PRIMARY KEY,
  type            TEXT NOT NULL,
  label           TEXT NOT NULL,
  description     TEXT NOT NULL DEFAULT '',
  executable_path TEXT,
  env_vars        TEXT NOT NULL DEFAULT '{}',
  created_at      INTEGER NOT NULL
, enabled_flag INTEGER NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS btw_queries (
  id TEXT PRIMARY KEY,
  parent_conv_id TEXT NOT NULL,
  child_conv_id TEXT,
  question TEXT NOT NULL,
  answer TEXT,
  status TEXT NOT NULL,                 -- 'asking' | 'done' | 'error'
  agent_id TEXT NOT NULL,
  model TEXT,
  error_message TEXT,
  created_at INTEGER NOT NULL,
  completed_at INTEGER, forked_conv_id TEXT,
  FOREIGN KEY (parent_conv_id) REFERENCES conversations(id) ON DELETE CASCADE,
  FOREIGN KEY (child_conv_id) REFERENCES conversations(id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS checkpoints (
  id                TEXT PRIMARY KEY,
  conversation_id   TEXT NOT NULL,
  event_id          TEXT NOT NULL,
  session_id        TEXT NOT NULL,
  native_session_id TEXT,
  native_turn_index INTEGER,
  code_ref          TEXT,
  label             TEXT,
  kind              TEXT NOT NULL DEFAULT 'auto'
                       CHECK (kind IN ('auto','manual')),
  pinned            INTEGER NOT NULL DEFAULT 0,
  created_at        INTEGER NOT NULL,
  FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  FOREIGN KEY (event_id)        REFERENCES events(id)        ON DELETE CASCADE,
  FOREIGN KEY (session_id)      REFERENCES sessions(id)      ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS conversations (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title       TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
, last_viewed_at INTEGER NOT NULL DEFAULT 0, parent_conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE, template_name TEXT, workdir_path TEXT, kind TEXT NOT NULL DEFAULT 'chat', schedule_job_id TEXT, spawn_workdir TEXT, pinned INTEGER NOT NULL DEFAULT 0, description TEXT, description_source TEXT, tags TEXT NOT NULL DEFAULT '[]', archived INTEGER NOT NULL DEFAULT 0, designation TEXT, capability_profile TEXT, auto_tagged_at INTEGER, stopped_at INTEGER, mcp_servers TEXT, permission_mode TEXT, pending_handoff_mode TEXT, rules TEXT, rule_preset_ids TEXT, sandbox TEXT, effort TEXT);

CREATE TABLE IF NOT EXISTS draft_prompts (
  conversation_id TEXT PRIMARY KEY
    REFERENCES conversations(id) ON DELETE CASCADE,
  text            TEXT    NOT NULL DEFAULT '',
  updated_at      INTEGER NOT NULL
, attachments TEXT NOT NULL DEFAULT '[]', processing            TEXT NOT NULL DEFAULT '', processing_id         TEXT, processing_started_at INTEGER, pre_text              TEXT, auto_send INTEGER NOT NULL DEFAULT 0, auto_send_profile_id TEXT, auto_send_agent TEXT, auto_send_model TEXT, profile_id TEXT);

CREATE TABLE IF NOT EXISTS events (
  id             TEXT PRIMARY KEY,
  session_id     TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,
  type           TEXT NOT NULL,
  payload        TEXT NOT NULL,
  sender         TEXT NOT NULL,
  agent_model_id TEXT REFERENCES agent_models(id),
  seq            INTEGER NOT NULL DEFAULT 0,
  ts             INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS projects (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  root_path   TEXT NOT NULL,
  created_at  INTEGER NOT NULL
, system INTEGER NOT NULL DEFAULT 0, rules TEXT, rule_preset_ids TEXT, remote_host_id TEXT REFERENCES remote_hosts(id), trust_repo_config INTEGER NOT NULL DEFAULT 0, sandbox TEXT, sandbox_paths TEXT, agent_search_scope TEXT
  CHECK (agent_search_scope IS NULL OR agent_search_scope IN ('off','project','all')));

CREATE TABLE IF NOT EXISTS "schedule_jobs" (
  id                      TEXT PRIMARY KEY,
  project_id              TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name                    TEXT NOT NULL,
  enabled                 INTEGER NOT NULL DEFAULT 1,
  archived                INTEGER NOT NULL DEFAULT 0,
  timezone                TEXT NOT NULL,
  schedule_kind           TEXT NOT NULL CHECK (schedule_kind IN ('interval','cron','once')),
  schedule_expr           TEXT NOT NULL,
  overlap_policy          TEXT NOT NULL DEFAULT 'skip'
                            CHECK (overlap_policy IN ('skip','queue_one','catch_up')),
  execution_mode          TEXT NOT NULL DEFAULT 'spawn_child'
                            CHECK (execution_mode IN ('spawn_child','resume_conversation')),
  profile_id              TEXT NOT NULL,
  role                    TEXT,
  bound_conversation_id   TEXT REFERENCES conversations(id),
  home_conversation_id    TEXT NOT NULL REFERENCES conversations(id),
  prompt_template         TEXT NOT NULL,
  run_timeout_ms          INTEGER NOT NULL DEFAULT 1800000,
  next_fire_at            INTEGER NOT NULL,
  agent_may_complete      INTEGER NOT NULL DEFAULT 0,
  carry_context_enabled   INTEGER NOT NULL DEFAULT 0,
  pending_context         TEXT,
  pending_context_source  TEXT CHECK (
                            pending_context_source IS NULL
                            OR pending_context_source IN ('operator','run','system')
                          ),
  pending_context_updated_at INTEGER,
  deferred_fire           INTEGER NOT NULL DEFAULT 0,
  workdir                 TEXT NOT NULL DEFAULT 'shared'
                            CHECK (workdir IN ('shared', 'worktree')),
  template_name           TEXT,
  steer                   TEXT,
  created_by              TEXT NOT NULL DEFAULT 'operator',
  created_by_conversation_id TEXT,
  created_at              INTEGER NOT NULL,
  updated_at              INTEGER NOT NULL
, variables TEXT, capability_profile TEXT);

CREATE TABLE IF NOT EXISTS schedule_runs (
  id                TEXT PRIMARY KEY,
  job_id            TEXT NOT NULL REFERENCES schedule_jobs(id) ON DELETE CASCADE,
  step_id           TEXT REFERENCES schedule_steps(id),
  conversation_id   TEXT REFERENCES conversations(id),
  status            TEXT NOT NULL DEFAULT 'pending'
                      CHECK (status IN ('pending','running','succeeded','failed','skipped','timed_out')),
  fired_at          INTEGER NOT NULL,
  finished_at       INTEGER,
  error             TEXT,
  outcome_summary   TEXT
);

CREATE TABLE IF NOT EXISTS schedule_steps (
  id                   TEXT PRIMARY KEY,
  job_id               TEXT NOT NULL REFERENCES schedule_jobs(id) ON DELETE CASCADE,
  ordinal              INTEGER NOT NULL,
  title                TEXT NOT NULL,
  body                 TEXT NOT NULL,
  status               TEXT NOT NULL DEFAULT 'pending'
                         CHECK (status IN ('pending','ready','running','done','blocked','skipped')),
  depends_on_step_id   TEXT REFERENCES schedule_steps(id),
  updated_at           INTEGER NOT NULL,
  UNIQUE (job_id, ordinal)
);

CREATE TABLE IF NOT EXISTS sessions (
  id                TEXT PRIMARY KEY,
  conversation_id   TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  agent_id          TEXT REFERENCES agents(id),
  agent_model_id    TEXT REFERENCES agent_models(id),
  native_session_id TEXT,
  created_at        INTEGER NOT NULL,
  updated_at        INTEGER NOT NULL
, input_tokens  INTEGER, output_tokens INTEGER, cost_usd      REAL, cache_read_tokens    INTEGER, cache_creation_tokens INTEGER, context_window_pct REAL, five_hour_pct      REAL, seven_day_pct      REAL, five_hour_resets_at INTEGER, seven_day_resets_at INTEGER, tokens_estimated INTEGER, preamble_fp TEXT);

CREATE TABLE IF NOT EXISTS settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS shell_allow (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  -- one prefix rule as a JSON token array, e.g. '["git","status"]'
  rule        TEXT NOT NULL,
  created_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS spawn_edges (
  id                     TEXT PRIMARY KEY,
  parent_conversation_id TEXT NOT NULL REFERENCES conversations(id),
  child_conversation_id  TEXT NOT NULL UNIQUE REFERENCES conversations(id),
  role                   TEXT,
  profile_id             TEXT,
  notify_parent          INTEGER NOT NULL DEFAULT 1,   -- 0/1
  status                 TEXT NOT NULL DEFAULT 'open', -- open|resolved|stalled|interrupted
  followup_count         INTEGER NOT NULL DEFAULT 0,
  created_at             INTEGER NOT NULL,             -- ms epoch
  resolved_at            INTEGER                       -- ms epoch
, outcome TEXT);

CREATE TABLE IF NOT EXISTS "spawn_requests" (
  id                     TEXT PRIMARY KEY,
  parent_conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  parent_session_id      TEXT NOT NULL,
  role                   TEXT,
  profile_id             TEXT,
  prompt                 TEXT NOT NULL,
  workdir                TEXT,
  wait                   INTEGER NOT NULL DEFAULT 0,
  notify_parent          INTEGER NOT NULL DEFAULT 0,
  status                 TEXT NOT NULL DEFAULT 'pending',
  child_conversation_id  TEXT,
  created_at             INTEGER NOT NULL,
  decided_at             INTEGER,
  decided_by             TEXT,
  error                  TEXT
, designation TEXT);

CREATE TABLE IF NOT EXISTS summaries (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL,
  last_event_id TEXT NOT NULL,
  summary_text TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  UNIQUE (conversation_id, last_event_id)
);

CREATE TABLE IF NOT EXISTS "tts_recordings" (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  conversation_id TEXT,
  created_at INTEGER NOT NULL,
  source TEXT NOT NULL,
  mode TEXT NOT NULL,
  provider TEXT NOT NULL,
  voice TEXT NOT NULL,
  title TEXT NOT NULL,
  spoken_text TEXT NOT NULL,
  path TEXT NOT NULL,
  bytes INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'done',
  error TEXT,
  updated_at INTEGER,
  ephemeral INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS push_subscriptions (
  endpoint   TEXT PRIMARY KEY,
  p256dh     TEXT NOT NULL,
  auth       TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  user_agent TEXT
);

CREATE TABLE IF NOT EXISTS agent_model_overrides (
  agent_id   TEXT NOT NULL,
  model_name TEXT NOT NULL,
  vision_override INTEGER,            -- NULL = no manual override, 0/1 = forced
  steer_override  INTEGER,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (agent_id, model_name)
) WITHOUT ROWID;

CREATE VIRTUAL TABLE IF NOT EXISTS event_fts USING fts5(body, content='', contentless_delete=1);

CREATE TABLE IF NOT EXISTS event_fts_buffer (
  session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE,
  body       TEXT NOT NULL DEFAULT ''
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS schedule_packs (
  slug        TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  version     INTEGER NOT NULL DEFAULT 1,
  origin      TEXT NOT NULL CHECK (origin IN ('shipped', 'imported')),
  doc         TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS plugin_secrets (
  plugin_id TEXT NOT NULL,
  key       TEXT NOT NULL,
  key_id    TEXT NOT NULL,          -- 'sess:v1' | 'env:v1' (F4)
  ciphertext BLOB NOT NULL,
  iv        BLOB NOT NULL,
  tag       BLOB NOT NULL,          -- AES-256-GCM auth tag
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (plugin_id, key)
);

CREATE TABLE IF NOT EXISTS plugin_invocations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts INTEGER NOT NULL,
  plugin_id TEXT NOT NULL,
  capability TEXT NOT NULL,
  caller_kind TEXT NOT NULL,        -- 'agent' | 'operator'
  conversation_id TEXT,
  ok INTEGER NOT NULL,
  duration_ms INTEGER NOT NULL,
  error TEXT                        -- safe message only; never key material
);

CREATE TABLE IF NOT EXISTS mesh_edges (
  id                TEXT PRIMARY KEY,
  -- Tree key: getRootAncestor(from_conversation) at mint time. Denormalised for
  -- indexing and for the Settings edge list. NOT the authorization input —
  -- canMessage() derives adjacency live.
  tree_root         TEXT NOT NULL,
  from_conversation TEXT NOT NULL,
  to_conversation   TEXT NOT NULL,
  -- 'operator' | 'agent:<conversationId>'
  minted_by         TEXT NOT NULL,
  -- 'tree' today. 'cross_project' RESERVED — no writer, no UI, rejected by
  -- canMessage() with decision 'denied_scope' if it ever appears.
  scope             TEXT NOT NULL DEFAULT 'tree',
  -- Perpetual until revoked. Nullable, no writer in v1, no UI. NULL = never expires.
  expires_at        INTEGER,
  created_at        INTEGER NOT NULL,
  revoked_at        INTEGER,
  note              TEXT
);

CREATE TABLE IF NOT EXISTS mesh_messages (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  ts                INTEGER NOT NULL,
  caller_kind       TEXT NOT NULL,
  from_conversation TEXT NOT NULL,
  to_conversation   TEXT NOT NULL,
  edge_id           TEXT,
  decision          TEXT NOT NULL,
  hop               INTEGER NOT NULL DEFAULT 0,
  bytes             INTEGER NOT NULL DEFAULT 0,
  content_sha256    TEXT,
  duration_ms       INTEGER NOT NULL DEFAULT 0,
  error             TEXT
);

CREATE TABLE IF NOT EXISTS git_commit_drafts (
  cwd                   TEXT PRIMARY KEY,
  message               TEXT NOT NULL DEFAULT '',
  generating            INTEGER NOT NULL DEFAULT 0,
  generating_started_at INTEGER,
  updated_at            INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS conversation_timers (
  id              TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  prompt          TEXT NOT NULL,
  profile_id      TEXT NOT NULL,
  fire_at_ms      INTEGER NOT NULL,
  created_at      INTEGER NOT NULL,
  cancelled_at    INTEGER,
  fired_at        INTEGER,
  error           TEXT
, effort TEXT, options TEXT, attachments TEXT, handoff_override TEXT, origin TEXT NOT NULL DEFAULT 'operator', attempt INTEGER NOT NULL DEFAULT 1, notify_parent INTEGER);

CREATE TABLE IF NOT EXISTS decision_usage (
  id              INTEGER PRIMARY KEY AUTOINCREMENT,
  ts              INTEGER NOT NULL,           -- epoch ms, call start
  consumer        TEXT    NOT NULL,           -- 'notify' | 'autotag' | 'test'
  conversation_id TEXT,                       -- nullable, NO foreign key
  model           TEXT    NOT NULL,
  input_tokens    INTEGER,                    -- NULL = response lacked usage / call failed
  output_tokens   INTEGER,
  latency_ms      INTEGER NOT NULL,
  outcome         TEXT    NOT NULL            -- 'ok' or the safe error reason from callSystemOne
);

CREATE TABLE IF NOT EXISTS global_tasks (
  id                  TEXT PRIMARY KEY,                       -- uuid
  project_id          TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  conversation_id     TEXT REFERENCES conversations(id) ON DELETE SET NULL,
  session_id          TEXT,                                   -- no FK: sessions are purged with their conversation
  conversation_title  TEXT NOT NULL DEFAULT '',               -- snapshot, survives conversation deletion
  title               TEXT NOT NULL,                          -- ≤ 200 chars, one line
  description         TEXT NOT NULL DEFAULT '',               -- ≤ 4000
  testing             TEXT NOT NULL DEFAULT '',               -- "testing needed", ≤ 4000
  progress            TEXT NOT NULL DEFAULT '',               -- "completed so far", ≤ 4000
  status              TEXT NOT NULL DEFAULT 'in_progress'
                      CHECK (status IN ('in_progress','completed')),
  completed_by        TEXT CHECK (completed_by IN ('agent','operator')),
  created_at          INTEGER NOT NULL,
  updated_at          INTEGER NOT NULL,                       -- any agent write or operator status change
  completed_at        INTEGER,
  hidden_at           INTEGER                                 -- operator "reviewed, hide"; NULL = visible
);

CREATE TABLE IF NOT EXISTS "handoffs" (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL,
  from_profile_id TEXT NOT NULL,
  to_profile_id TEXT NOT NULL,
  requested_mode TEXT NOT NULL CHECK (requested_mode IN ('summary', 'transcript', 'fresh')),
  resolved_mode TEXT NOT NULL CHECK (resolved_mode IN ('compacted', 'transcript', 'fresh')),
  anchor_event_id TEXT NOT NULL,
  summary_id TEXT,
  created_at INTEGER NOT NULL, priming_context TEXT,
  FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
  FOREIGN KEY (summary_id) REFERENCES summaries(id) ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS mcp_servers (
  id                  TEXT PRIMARY KEY,
  transport           TEXT NOT NULL CHECK (transport IN ('stdio','http','sse')),
  command             TEXT,
  args                TEXT NOT NULL DEFAULT '[]',
  cwd                 TEXT,
  url                 TEXT,
  env                 TEXT NOT NULL DEFAULT '[]',
  headers             TEXT NOT NULL DEFAULT '[]',
  description         TEXT,
  enabled             INTEGER NOT NULL DEFAULT 1,
  allow_in_delegating INTEGER NOT NULL DEFAULT 0,
  agent_types         TEXT,
  created_at          INTEGER NOT NULL,
  updated_at          INTEGER NOT NULL
, placement TEXT NOT NULL DEFAULT 'auto'
  CHECK (placement IN ('auto', 'agent', 'hub')));

CREATE TABLE IF NOT EXISTS rule_presets (
  id          TEXT PRIMARY KEY,
  project_id  TEXT REFERENCES projects(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  description TEXT,
  content     TEXT NOT NULL,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS remote_hosts (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','enrolled','trusted','disabled')),
  enroll_token_hash TEXT,
  enroll_expires_at INTEGER,
  public_key TEXT,
  hub_origin TEXT,
  hello TEXT NOT NULL DEFAULT '{}',
  last_seen_at INTEGER,
  transport TEXT NOT NULL DEFAULT 'wss' CHECK (transport IN ('wss','ssh')),
  ssh_target TEXT,
  ssh_identity_file TEXT,
  ssh_host_key TEXT,
  allow_mcp_secrets INTEGER NOT NULL DEFAULT 1,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, auto_trust INTEGER NOT NULL DEFAULT 1, description TEXT, allow_agent_env_secrets INTEGER NOT NULL DEFAULT 0);

CREATE TABLE IF NOT EXISTS memories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,            -- AUTOINCREMENT: a deleted m_N is never reused
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('gotcha','decision','fact')),
  text TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','flagged','superseded')),
  superseded_by INTEGER REFERENCES memories(id) ON DELETE SET NULL,
  rule_suggestion TEXT CHECK (rule_suggestion IN ('pending','dismissed','promoted')),
  rule_reason TEXT,
  flag_reason TEXT,
  created_by_agent TEXT,
  created_by_conversation TEXT,                    -- deliberately no FK: outlives retention
  created_at INTEGER NOT NULL
);

CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(text, tokenize='porter unicode61');

CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_commands_unique ON agent_commands(agent_id, name);

CREATE INDEX IF NOT EXISTS idx_agent_models_agent ON agent_models(agent_id);

CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_models_unique ON agent_models(agent_id, model_name);

CREATE INDEX IF NOT EXISTS idx_btw_parent ON btw_queries(parent_conv_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_checkpoints_conversation ON checkpoints(conversation_id, created_at);

CREATE UNIQUE INDEX IF NOT EXISTS idx_checkpoints_event  ON checkpoints(event_id);

CREATE INDEX IF NOT EXISTS idx_conversations_parent ON conversations(parent_conversation_id);

CREATE INDEX IF NOT EXISTS idx_conversations_project ON conversations(project_id);

CREATE INDEX IF NOT EXISTS idx_conversations_schedule_job
  ON conversations(schedule_job_id) WHERE schedule_job_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_events_session ON events(session_id, ts);

CREATE INDEX IF NOT EXISTS idx_schedule_jobs_due
  ON schedule_jobs(next_fire_at) WHERE enabled = 1 AND archived = 0;

CREATE INDEX IF NOT EXISTS idx_schedule_jobs_project
  ON schedule_jobs(project_id);

CREATE INDEX IF NOT EXISTS idx_schedule_runs_active
  ON schedule_runs(job_id, status) WHERE status IN ('pending','running');

CREATE INDEX IF NOT EXISTS idx_schedule_runs_job ON schedule_runs(job_id, fired_at DESC);

CREATE INDEX IF NOT EXISTS idx_schedule_steps_job ON schedule_steps(job_id);

CREATE INDEX IF NOT EXISTS idx_sessions_conversation ON sessions(conversation_id);

CREATE INDEX IF NOT EXISTS idx_shell_allow_project ON shell_allow(project_id);

CREATE INDEX IF NOT EXISTS idx_spawn_edges_open ON spawn_edges(status) WHERE status = 'open';

CREATE INDEX IF NOT EXISTS idx_spawn_edges_parent ON spawn_edges(parent_conversation_id);

CREATE INDEX IF NOT EXISTS idx_spawn_requests_parent
  ON spawn_requests(parent_conversation_id);

CREATE INDEX IF NOT EXISTS idx_spawn_requests_pending
  ON spawn_requests(status) WHERE status = 'pending';

CREATE INDEX IF NOT EXISTS idx_summaries_conversation ON summaries(conversation_id);

CREATE INDEX IF NOT EXISTS idx_tts_recordings_conversation
  ON tts_recordings(conversation_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_tts_recordings_project
  ON tts_recordings(project_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_events_session_seq ON events(session_id, seq);

CREATE INDEX IF NOT EXISTS idx_plugin_invocations_plugin_id ON plugin_invocations (plugin_id, id DESC);

CREATE UNIQUE INDEX IF NOT EXISTS idx_mesh_edges_live_pair
  ON mesh_edges (from_conversation, to_conversation)
  WHERE revoked_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_mesh_edges_from ON mesh_edges (from_conversation, revoked_at);

CREATE INDEX IF NOT EXISTS idx_mesh_edges_tree ON mesh_edges (tree_root, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_mesh_messages_to ON mesh_messages (to_conversation, ts DESC);

CREATE INDEX IF NOT EXISTS idx_mesh_messages_ts ON mesh_messages (ts DESC);

CREATE INDEX IF NOT EXISTS idx_conversation_timers_conv
  ON conversation_timers (conversation_id);

CREATE INDEX IF NOT EXISTS idx_conversation_timers_due
  ON conversation_timers (fire_at_ms)
  WHERE fired_at IS NULL AND cancelled_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_conversation_timers_auto
  ON conversation_timers (conversation_id, origin)
  WHERE fired_at IS NULL AND cancelled_at IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_conversation_timers_one_pending_agent
  ON conversation_timers(conversation_id)
  WHERE origin <> 'operator' AND fired_at IS NULL AND cancelled_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_decision_usage_ts ON decision_usage(ts);

CREATE INDEX IF NOT EXISTS idx_global_tasks_open ON global_tasks (status, hidden_at, updated_at);

CREATE INDEX IF NOT EXISTS idx_global_tasks_conv ON global_tasks (conversation_id);

CREATE INDEX IF NOT EXISTS idx_handoffs_anchor ON handoffs(conversation_id, anchor_event_id);

CREATE INDEX IF NOT EXISTS idx_handoffs_conversation ON handoffs(conversation_id);

CREATE INDEX IF NOT EXISTS idx_rule_presets_project ON rule_presets(project_id);

CREATE INDEX IF NOT EXISTS idx_memories_project ON memories(project_id, status, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_memories_pending ON memories(project_id) WHERE rule_suggestion = 'pending';

CREATE INDEX IF NOT EXISTS idx_events_status_session
  ON events(session_id) WHERE type = 'status';

CREATE INDEX IF NOT EXISTS idx_events_user_tool_call
  ON events(session_id) WHERE type = 'tool_call' AND sender = 'user';

CREATE INDEX IF NOT EXISTS idx_events_tool_result_use_id
  ON events(json_extract(payload, '$.toolUseId')) WHERE type = 'tool_result';

CREATE TRIGGER IF NOT EXISTS event_fts_ai_prompt AFTER INSERT ON events
WHEN new.type = 'prompt'
 AND json_extract(new.payload, '$.text') IS NOT NULL
 AND json_extract(new.payload, '$.text') <> ''
BEGIN
  INSERT INTO event_fts(rowid, body)
  VALUES (new.rowid, substr(json_extract(new.payload, '$.text'), 1, 8000));
END;

CREATE TRIGGER IF NOT EXISTS event_fts_ai_message_whole AFTER INSERT ON events
WHEN new.type = 'message'
 AND json_extract(new.payload, '$.final') IS NULL
 AND json_extract(new.payload, '$.chunk') IS NOT NULL
 AND json_extract(new.payload, '$.chunk') <> ''
BEGIN
  INSERT INTO event_fts(rowid, body)
  VALUES (new.rowid, substr(json_extract(new.payload, '$.chunk'), 1, 8000));
END;

CREATE TRIGGER IF NOT EXISTS event_fts_ai_message_chunk AFTER INSERT ON events
WHEN new.type = 'message'
 AND json_extract(new.payload, '$.final') = 0
 AND json_extract(new.payload, '$.chunk') <> ''
BEGIN
  INSERT INTO event_fts_buffer(session_id, body)
  VALUES (new.session_id, json_extract(new.payload, '$.chunk'))
  ON CONFLICT(session_id)
  DO UPDATE SET body = substr(body || json_extract(new.payload, '$.chunk'), 1, 8000);
END;

CREATE TRIGGER IF NOT EXISTS event_fts_ai_message_final AFTER INSERT ON events
WHEN new.type = 'message'
 AND json_extract(new.payload, '$.final') = 1
BEGIN
  INSERT INTO event_fts(rowid, body)
  SELECT new.rowid,
         substr(COALESCE((SELECT body FROM event_fts_buffer WHERE session_id = new.session_id), '')
                || COALESCE(json_extract(new.payload, '$.chunk'), ''), 1, 8000)
   WHERE COALESCE((SELECT body FROM event_fts_buffer WHERE session_id = new.session_id), '')
         || COALESCE(json_extract(new.payload, '$.chunk'), '') <> '';
  DELETE FROM event_fts_buffer WHERE session_id = new.session_id;
END;

CREATE TRIGGER IF NOT EXISTS event_fts_ai_helper AFTER INSERT ON events
WHEN new.type = 'helper'
 AND json_extract(new.payload, '$.status') IN ('completed', 'failed', 'stopped')
 AND trim(COALESCE(json_extract(new.payload, '$.label'), '') || ' ' ||
          COALESCE(json_extract(new.payload, '$.description'), '') || ' ' ||
          COALESCE(json_extract(new.payload, '$.summary'), '')) <> ''
BEGIN
  DELETE FROM event_fts WHERE rowid IN (
    SELECT rowid FROM events
     WHERE session_id = new.session_id
       AND type = 'helper'
       AND json_extract(payload, '$.taskId') = json_extract(new.payload, '$.taskId')
       AND rowid <> new.rowid
  );
  INSERT INTO event_fts(rowid, body)
  VALUES (new.rowid, substr(trim(
    COALESCE(json_extract(new.payload, '$.label'), '') || ' ' ||
    COALESCE(json_extract(new.payload, '$.description'), '') || ' ' ||
    COALESCE(json_extract(new.payload, '$.summary'), '')
  ), 1, 8000));
END;

CREATE TRIGGER IF NOT EXISTS event_fts_ad AFTER DELETE ON events
BEGIN
  DELETE FROM event_fts WHERE rowid = old.rowid;
END;

CREATE TRIGGER IF NOT EXISTS event_fts_au AFTER UPDATE OF payload ON events
BEGIN
  DELETE FROM event_fts WHERE rowid = old.rowid;
  INSERT INTO event_fts(rowid, body)
  SELECT new.rowid,
         substr(COALESCE(json_extract(new.payload, '$.text'),
                         json_extract(new.payload, '$.chunk')), 1, 8000)
   WHERE new.type IN ('prompt', 'message')
     AND COALESCE(json_extract(new.payload, '$.text'),
                  json_extract(new.payload, '$.chunk'), '') <> '';
  INSERT INTO event_fts(rowid, body)
  SELECT new.rowid, substr(trim(
    COALESCE(json_extract(new.payload, '$.label'), '') || ' ' ||
    COALESCE(json_extract(new.payload, '$.description'), '') || ' ' ||
    COALESCE(json_extract(new.payload, '$.summary'), '')
  ), 1, 8000)
   WHERE new.type = 'helper'
     AND json_extract(new.payload, '$.status') IN ('completed', 'failed', 'stopped')
     AND trim(COALESCE(json_extract(new.payload, '$.label'), '') || ' ' ||
              COALESCE(json_extract(new.payload, '$.description'), '') || ' ' ||
              COALESCE(json_extract(new.payload, '$.summary'), '')) <> '';
END;

CREATE TRIGGER IF NOT EXISTS memories_fts_ai AFTER INSERT ON memories BEGIN
  INSERT INTO memories_fts(rowid, text) VALUES (new.id, new.text);
END;

CREATE TRIGGER IF NOT EXISTS memories_fts_ad AFTER DELETE ON memories BEGIN
  DELETE FROM memories_fts WHERE rowid = old.id;
END;

-- Seed rows the squashed chain inserted on a fresh DB.
INSERT OR IGNORE INTO settings (key, value) VALUES ('sandbox', '{"global":false,"defaults":[],"hostPaths":{}}');

-- Backfill: latest terminal helper snapshot per (session_id, taskId).
-- Idempotent: skip rowids already in event_fts (fresh DBs have none; live
-- installs that already ran event_fts_ai_helper keep theirs).
INSERT INTO event_fts(rowid, body)
SELECT e.rowid, substr(trim(
  COALESCE(json_extract(e.payload, '$.label'), '') || ' ' ||
  COALESCE(json_extract(e.payload, '$.description'), '') || ' ' ||
  COALESCE(json_extract(e.payload, '$.summary'), '')
), 1, 8000)
  FROM events e
 WHERE e.type = 'helper'
   AND json_extract(e.payload, '$.status') IN ('completed', 'failed', 'stopped')
   AND trim(COALESCE(json_extract(e.payload, '$.label'), '') || ' ' ||
            COALESCE(json_extract(e.payload, '$.description'), '') || ' ' ||
            COALESCE(json_extract(e.payload, '$.summary'), '')) <> ''
   AND e.rowid = (
     SELECT MAX(e2.rowid) FROM events e2
      WHERE e2.type = 'helper'
        AND e2.session_id = e.session_id
        AND json_extract(e2.payload, '$.taskId') IS json_extract(e.payload, '$.taskId')
        AND json_extract(e2.payload, '$.status') IN ('completed', 'failed', 'stopped')
   )
   AND NOT EXISTS (SELECT 1 FROM event_fts f WHERE f.rowid = e.rowid);
